280	<script>
281	  const deck = document.getElementById('deck');
282	  const slides = Array.from(deck.children);
283	  const dotsEl = document.getElementById('dots');
284	  const curEl = document.getElementById('cur');
285	  document.getElementById('tot').textContent = slides.length;
286	
287	  slides.forEach((_, i) => {
288	    const b = document.createElement('button');
289	    b.setAttribute('aria-label', 'Go to slide ' + (i + 1));
290	    b.addEventListener('click', () => goTo(i));
291	    dotsEl.appendChild(b);
292	  });
293	  const dotButtons = Array.from(dotsEl.children);
294	
295	  let current = 0;
296	  function setActive(i) {
297	    current = i;
298	    dotButtons.forEach((b, j) => b.setAttribute('aria-current', j === i ? 'true' : 'false'));
299	    curEl.textContent = i + 1;
300	  }
301	  function goTo(i) {
302	    i = Math.max(0, Math.min(slides.length - 1, i));
303	    slides[i].scrollIntoView({ behavior: 'smooth', inline: 'start' });
304	  }
305	
306	  let ticking = false;
307	  deck.addEventListener('scroll', () => {
308	    if (ticking) return;
309	    ticking = true;
310	    requestAnimationFrame(() => {
311	      const i = Math.round(deck.scrollLeft / window.innerWidth);
312	      setActive(Math.max(0, Math.min(slides.length - 1, i)));
313	      ticking = false;
314	    });
315	  });
316	
317	  document.getElementById('prev').addEventListener('click', () => goTo(current - 1));
318	  document.getElementById('next').addEventListener('click', () => goTo(current + 1));
319

